data_contract.table:
id bigIncrements;
type string(20) NOT NULL, index — bank_account|card|cash;
name string(255) NOT NULL — Banca (bank_account, card) / Nome (cash);
company_id FK companies nullable, nullOnDelete, index;
iban string(34) nullable, UNIQUE — solo bank_account, normalizzato (maiuscolo, senza spazi);
account_number string(50) nullable — solo bank_account ("Conto Corrente");
address_line string(255) nullable; postal_code string(10) nullable;
country_id / state_id / province_id / city_id FK nullable, nullOnDelete — bank_account, cash;
card_type string(20) nullable — credit|prepaid, solo card;
card_circuit string(20) nullable — visa|mastercard|amex, solo card;
linked_account_id FK financial_accounts nullable, restrictOnDelete, index — solo card;
card_holder string(255) nullable — solo card;
card_number text nullable, cast `encrypted`, $hidden — solo card;
card_last_four char(4) nullable — derivato server-side;
card_expiry string(7) nullable — `MM/YYYY`, solo card;
notes text nullable;
timestamps.

data_contract.payload:
{ type: "cash", name: string (req, max 255), company_id: int|null,
  address_line, postal_code, country_id, state_id, province_id, city_id (come bank_account), notes }
Campi bank/carta presenti => 422 (prohibited).
